const MAX = 6000;                 // characters per chunk
const text = $input.first().json.text || '';
const file = $('Google Drive Trigger').first().json.name;
const runId = `${new Date().toISOString().slice(0,10)}-${$execution.id}`;

const out = [];
// split on page breaks first, then pack pages into chunks
const pages = text.split('\f');
let buf = '';
for (const page of pages) {
  if ((buf + page).length > MAX && buf) {
    out.push(buf); buf = page;
  } else {
    buf += '\f' + page;
  }
}
if (buf.trim()) out.push(buf);

return out.map((t, i) => ({
  json: { run_id: runId, source_file: file, chunk_index: i, text: t }
}));

const slug = s => String(s || '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const p = item.json["output.products"] || item.json;
  const problems = [];

  // SKU: use theirs, else build a stable one
  let sku = slug(p.sku);
  if (!sku) sku = slug(`${p.brand || 'GEN'}-${p.model || p.name}`).slice(0, 40);
  if (!sku) problems.push('no sku');

  // duplicate within this same file
  if (seen.has(sku)) { problems.push('duplicate in file'); }
  seen.add(sku);

  const price = typeof p.supplier_price === 'number' ? p.supplier_price : null;
  if (price === null) problems.push('no price');
  if (price !== null && price <= 0) problems.push('price is zero or negative');

  const srp = typeof p.srp === 'number' ? p.srp : null;
  if (srp === null) problems.push('no SRP');
  if (srp !== null && srp <= 0) problems.push('SRP is zero or negative');

  if (!p.name) problems.push('no name');
  if ((p.confidence ?? 0) < 0.6) problems.push('low confidence');



  out.push({ json: {
    run_id: item.json['run_id'],
    source_file: item.json['source_file'],
    sku,
    name: String(p.name || '').trim().slice(0, 180),
    brand: /* p.brand ||  */'',
    model: p.model || '',
    supplier_price: price,
    srp: srp,
    markup_pct: 0,
    short_description: p.short_description || '',
    description: p.description || '',
    specs_json: JSON.stringify(p.specs || []),
    supplier_category: p.supplier_category || '',
    category: p.category || '',
    stock_qty: p.stock_qty ?? '',
    publish_at: '',
    approved: problems.length > 0 ? 'FALSE' : 'TRUE',
    confidence: p.confidence ?? 0,
    notes: problems.join('; '),
    needs_attention: problems.length > 0,
    status: 'pending',
  }});
}


return out;

const REMOVE_EMPTY = true; // set false to keep items with no products

// mm -> cm, 1 decimal
const toCm = (n, isCm) => isCm ? Number(n) : Number((Number(n) / 10).toFixed(1));

function parseDimensions(raw) {
  if (typeof raw !== 'string') return null;
  const isCm = /\bcm\b/i.test(raw);

  const parts = raw
    .replace(/[\[\]]/g, '')      // remove brackets: "[714, 416-576, 250]"
    .replace(/mm|cm/gi, '')      // remove units
    .split(/\s*[x,]\s*/i)        // split on "x" or ","
    .map(s => s.trim())
    .filter(Boolean);

  const result = [];
  for (const p of parts) {
    const range = p.match(/^(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)$/);
    if (range) {
      result.push({ min: toCm(range[1], isCm), max: toCm(range[2], isCm) });
    } else if (/^\d+(\.\d+)?$/.test(p)) {
      result.push(toCm(p, isCm));
    } else {
      return null; // not numeric, e.g. "Adjustable headband"
    }
  }
  return result.length ? result : null;
}

const out = [];

for (const item of $input.all()) {
  const products = item.json.output?.products ?? [];
  if (REMOVE_EMPTY && products.length === 0) continue;

  for (const product of products) {
    for (const spec of product.specs ?? []) {
      if (!/^dimensions/i.test(spec.key)) continue;

      const parsed = parseDimensions(spec.value);
      if (parsed) {
        spec.key = 'Dimensions (WxHxD)'; // normalize key name
        spec.value = parsed;
        spec.unit = 'cm';
      }
      // if not parseable, the original text is left as-is
    }
  }
  out.push(item);
}

return out;
